import java.io.IOException
import java.nio.file.Files
import java.nio.file.LinkOption

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
}

tasks.jar {
    manifest {
        attributes["Main-Class"] = "org.example.App"
    }

    duplicatesStrategy = DuplicatesStrategy.EXCLUDE
    from({
        configurations.runtimeClasspath.get().map {
            if (it.isDirectory) it else zipTree(it)
        }
    })
    exclude("META-INF/*.SF", "META-INF/*.DSA", "META-INF/*.RSA")
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit test framework.
    testImplementation(libs.junit)

    compileOnly("org.projectlombok:lombok:1.18.42")
    annotationProcessor("org.projectlombok:lombok:1.18.42")

    testCompileOnly("org.projectlombok:lombok:1.18.42")
    testAnnotationProcessor("org.projectlombok:lombok:1.18.42")

    implementation("com.fasterxml.jackson.core:jackson-databind:2.20.0")
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17)
    }
}

application {
    // Define the main class for the application.
    mainClass = "org.example.App"
}

val linkJdk = tasks.register("linkJdk") {
    description = "Links the toolchain JDK into the worker directory for direct spawning."
    group = "build"

    val link = rootProject.layout.projectDirectory.dir(".jdk").asFile
    val jdkHome = javaToolchains.launcherFor(java.toolchain).map { it.metadata.installationPath.asFile }

    doLast {
        val target = jdkHome.get()

        val current =
            try {
                link.toPath().toRealPath()
            } catch (_: IOException) {
                null
            }

        if (current == target.toPath().toRealPath()) {
            return@doLast
        }

        if (Files.exists(link.toPath(), LinkOption.NOFOLLOW_LINKS)) {
            Files.delete(link.toPath())
        }

        val linked =
            if (System.getProperty("os.name").lowercase().contains("win")) {
                val exitCode =
                    ProcessBuilder(
                        "cmd", "/c", "mklink", "/J", link.absolutePath, target.absolutePath
                    )
                        .redirectErrorStream(true)
                        .start()
                        .also { it.inputStream.readAllBytes() }
                        .waitFor()

                exitCode == 0
            } else {
                Files.createSymbolicLink(link.toPath(), target.toPath())
                true
            }

        if (!linked) {
            throw GradleException("could not link ${link.absolutePath} to ${target.absolutePath}")
        }
    }
}

tasks.named("jar") {
    dependsOn(linkJdk)
}
